using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using Peletnapechkai.Api.Domain.Content;
namespace Peletnapechkai.Api.Infrastructure.Persistence.Configurations;
internal sealed class EditorialTaskConfiguration:IEntityTypeConfiguration<EditorialTask>{public void Configure(EntityTypeBuilder<EditorialTask>b){b.ToTable("editorial_tasks");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.ArticleLocalizationId).HasColumnName("article_localization_id");b.Property(x=>x.AssigneeUserId).HasColumnName("assignee_user_id");b.Property(x=>x.Title).HasColumnName("title").HasMaxLength(300);b.Property(x=>x.Priority).HasColumnName("priority").HasConversion<string>().HasMaxLength(16);b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.DueAt).HasColumnName("due_at");b.Property(x=>x.CreatedByUserId).HasColumnName("created_by_user_id");b.Property(x=>x.CreatedAt).HasColumnName("created_at");b.Property(x=>x.UpdatedAt).HasColumnName("updated_at");b.HasOne(x=>x.Article).WithMany().HasForeignKey(x=>x.ArticleLocalizationId).OnDelete(DeleteBehavior.Cascade);b.HasIndex(x=>new{x.AssigneeUserId,x.Status,x.DueAt}).HasDatabaseName("ix_editorial_tasks_assignee_status_due");}}
internal sealed class EditorialCommentConfiguration:IEntityTypeConfiguration<EditorialComment>{public void Configure(EntityTypeBuilder<EditorialComment>b){b.ToTable("editorial_comments");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.ArticleLocalizationId).HasColumnName("article_localization_id");b.Property(x=>x.AuthorUserId).HasColumnName("author_user_id");b.Property(x=>x.Body).HasColumnName("body").HasMaxLength(4000);b.Property(x=>x.ParentCommentId).HasColumnName("parent_comment_id");b.Property(x=>x.ArticleRevisionId).HasColumnName("article_revision_id");b.Property(x=>x.IsResolved).HasColumnName("is_resolved");b.Property(x=>x.DeletedAt).HasColumnName("deleted_at");b.Property(x=>x.DeletedByUserId).HasColumnName("deleted_by_user_id");b.Property(x=>x.CreatedAt).HasColumnName("created_at");b.Property(x=>x.UpdatedAt).HasColumnName("updated_at");b.HasOne(x=>x.Article).WithMany().HasForeignKey(x=>x.ArticleLocalizationId).OnDelete(DeleteBehavior.Cascade);b.HasIndex(x=>new{x.ArticleLocalizationId,x.CreatedAt}).HasDatabaseName("ix_editorial_comments_article_created");}}
internal sealed class ArticleQualityChecklistConfiguration:IEntityTypeConfiguration<ArticleQualityChecklist>{public void Configure(EntityTypeBuilder<ArticleQualityChecklist>b){b.ToTable("article_quality_checklists");b.HasKey(x=>x.ArticleLocalizationId);b.Property(x=>x.ArticleLocalizationId).HasColumnName("article_localization_id").ValueGeneratedNever();b.Property(x=>x.TitleAndSummary).HasColumnName("title_and_summary");b.Property(x=>x.SourcesVerified).HasColumnName("sources_verified");b.Property(x=>x.AuthorAndTaxonomy).HasColumnName("author_and_taxonomy");b.Property(x=>x.SeoMetadata).HasColumnName("seo_metadata");b.Property(x=>x.CoverAccessibility).HasColumnName("cover_accessibility");b.Property(x=>x.CommercialDisclosure).HasColumnName("commercial_disclosure");b.Property(x=>x.TranslationReviewed).HasColumnName("translation_reviewed");b.Property(x=>x.LegalEditorialReview).HasColumnName("legal_editorial_review");b.Property(x=>x.UpdatedByUserId).HasColumnName("updated_by_user_id");b.Property(x=>x.UpdatedAt).HasColumnName("updated_at");b.Ignore(x=>x.IsComplete);b.HasOne(x=>x.Article).WithOne().HasForeignKey<ArticleQualityChecklist>(x=>x.ArticleLocalizationId).OnDelete(DeleteBehavior.Cascade);}}
